#!/usr/bin/env node
/**
 * sync-from-hal0-web.mjs
 *
 * Regenerates the AUTO-GENERATED files in this repo from a checkout of
 * hal0-web, so brand tokens and nav links are never hand-forked here.
 *
 * Source of truth (in hal0-web):
 *   - src/styles/tokens.css   -> stylesheets/_hal0-tokens.scss
 *   - src/data/nav.json       -> javascripts/discourse/lib/hal0-nav-data.js
 *
 * Usage:
 *   node scripts/sync-from-hal0-web.mjs [path-to-hal0-web-checkout]
 *   HAL0_WEB_DIR=/mnt/mintdev/repos/hal0-web node scripts/sync-from-hal0-web.mjs
 *
 * Resolution order for the hal0-web checkout path: CLI arg > HAL0_WEB_DIR
 * env var > ../hal0-web relative to this repo (sibling checkout).
 */
import { readFileSync, writeFileSync, existsSync, mkdirSync } from "node:fs";
import { resolve, dirname } from "node:path";
import { fileURLToPath } from "node:url";

const __dirname = dirname(fileURLToPath(import.meta.url));
const repoRoot = resolve(__dirname, "..");

const hal0WebDir = resolve(
  process.argv[2] || process.env.HAL0_WEB_DIR || resolve(repoRoot, "../hal0-web")
);

const tokensPath = resolve(hal0WebDir, "src/styles/tokens.css");
const navPath = resolve(hal0WebDir, "src/data/nav.json");

for (const [label, p] of [["tokens.css", tokensPath], ["nav.json", navPath]]) {
  if (!existsSync(p)) {
    console.error(`error: could not find ${label} at ${p}`);
    console.error("Pass the hal0-web checkout path as an argument or set HAL0_WEB_DIR.");
    process.exit(1);
  }
}

// ---------------------------------------------------------------------------
// 1. tokens.css -> stylesheets/_hal0-tokens.scss
// ---------------------------------------------------------------------------

function extractDeclBlock(css, selectorRe) {
  const m = selectorRe.exec(css);
  if (!m) return null;
  const start = m.index + m[0].length;
  const end = css.indexOf("}", start);
  return css.slice(start, end);
}

function parseDecls(block) {
  // NOTE: this regex terminates a value at the first `;`, which is correct
  // for every token in tokens.css today (plain hex/rgba/keyword values with
  // no embedded semicolons). If a future token's value ever legitimately
  // contains a `;` (e.g. a data: URI, or a multi-fallback font stack quoted
  // in a way that includes one), this will silently truncate it — there's
  // no guard against that here, just this warning for whoever hits it.
  const out = [];
  const re = /--([a-z0-9-]+)\s*:\s*([^;]+);/gi;
  let m;
  while ((m = re.exec(block))) {
    out.push([m[1].trim(), m[2].trim()]);
  }
  return out;
}

const tokensCss = readFileSync(tokensPath, "utf8");

const rootBlock = extractDeclBlock(tokensCss, /:root\s*{/);
const lightBlock = extractDeclBlock(tokensCss, /\[data-theme=['"]light['"]\]\s*{/);

if (!rootBlock || !lightBlock) {
  console.error("error: could not locate :root or [data-theme='light'] block in tokens.css");
  process.exit(1);
}

const darkDecls = parseDecls(rootBlock);
const lightDecls = parseDecls(lightBlock);
const lightNames = new Set(lightDecls.map(([name]) => name));

// Split on whether a token has a light override: those tokens differ per
// color scheme, so they belong in common/color_definitions.scss (compiled
// once per Discourse ColorScheme — see that file's header comment). Tokens
// with no light override are identical in both schemes, so they stay in
// this single-compile partial. This split is derived from the data, not
// hand-maintained, so a new token in tokens.css lands in the right file
// automatically the next time this script runs.
const invariantDecls = darkDecls.filter(([name]) => !lightNames.has(name));
const swappableDecls = darkDecls.filter(([name]) => lightNames.has(name));
const lightByName = new Map(lightDecls);

const renderDecls = (decls, indent = "  ") =>
  decls.map(([name, value]) => `${indent}--${name}: ${value};`).join("\n");

const tokensScss = `// AUTO-GENERATED by scripts/sync-from-hal0-web.mjs — do not edit by hand.
// Source: hal0-web src/styles/tokens.css
// Regenerate with: node scripts/sync-from-hal0-web.mjs [hal0-web-dir]
//
// Tokens that are IDENTICAL in both hal0-web color schemes (no light
// override in tokens.css) — fonts, radii, letter-spacing, motion, shadows.
// This partial is @imported once by common/common.scss, so it can only ever
// emit one value per token; anything that needs to differ between light and
// dark lives in ../common/color_definitions.scss instead, which Discourse
// compiles once per ColorScheme and can therefore pick a different value
// per scheme. See that file's header for why "once per scheme" matters and
// why this is no longer a \`@media (prefers-color-scheme: light)\` split.

:root {
${renderDecls(invariantDecls)}
}

// Force-light escape hatch, mirrored from hal0-web. Not consumed by this
// theme today (nothing here forces light mode), kept for parity in case a
// future connector needs it. Includes the scheme-swappable tokens too,
// since "force light" means literal light values regardless of which
// Discourse color scheme is compiling this partial.
.hal0-force-light {
${renderDecls(invariantDecls.filter(([name]) => !lightByName.has(name)))}
${renderDecls(swappableDecls.map(([name]) => [name, lightByName.get(name)]))}
}
`;

mkdirSync(resolve(repoRoot, "stylesheets"), { recursive: true });
writeFileSync(resolve(repoRoot, "stylesheets/_hal0-tokens.scss"), tokensScss);
console.log(
  `wrote stylesheets/_hal0-tokens.scss (${invariantDecls.length} scheme-invariant tokens)`
);

// ---------------------------------------------------------------------------
// 1b. tokens.css -> common/color_definitions.scss (scheme-swappable tokens)
// ---------------------------------------------------------------------------
//
// Discourse compiles a `common/color_definitions.scss` file ONCE PER COLOR
// SCHEME (see lib/stylesheet/manager.rb's COLOR_SCHEME_STYLESHEET target),
// unlike common/common.scss which compiles once total. Inside it, core
// exposes `dark-light-choose($light-result, $dark-result)` (see
// app/assets/stylesheets/common/foundation/variables.scss), which picks one
// of its two arguments based on the *currently compiling* scheme's actual
// brightness (comparing $primary vs $secondary), not on OS preference or
// any hand-authored condition. That's what makes this scheme-aware in a way
// a plain `@media (prefers-color-scheme: light)` block never could be: the
// active <link class="light-scheme"|"dark-scheme"> stylesheet is what
// Discourse's own light/dark toggle (`interface_color_selector`) swaps, and
// each of those links is a full compiled color_definitions.scss for that
// scheme — so these custom properties flip in lockstep with core's own
// --primary/--secondary/etc, including a manual toggle that disagrees with
// the OS. Must live at exactly this path — Discourse discovers it as a
// single named theme field (common/color_definitions.scss), not through
// common.scss's @import chain, so it is NOT @imported anywhere.
const colorDefinitionsScss = `// AUTO-GENERATED by scripts/sync-from-hal0-web.mjs — do not edit by hand.
// Source: hal0-web src/styles/tokens.css
// Regenerate with: node scripts/sync-from-hal0-web.mjs [hal0-web-dir]
//
// Compiled once per Discourse ColorScheme (see lib/stylesheet/manager.rb).
// dark-light-choose($light, $dark) resolves per the *compiling* scheme's
// actual brightness (core's is-light-color-scheme(), comparing $primary vs
// $secondary) — see ../stylesheets/_hal0-tokens.scss for the full
// rationale. Do not @import this file; Discourse compiles it as its own
// target by exact path.

:root {
${swappableDecls
  .map(
    ([name, darkValue]) =>
      `  --${name}: #{dark-light-choose(${lightByName.get(name)}, ${darkValue})};`
  )
  .join("\n")}
}
`;

mkdirSync(resolve(repoRoot, "common"), { recursive: true });
writeFileSync(resolve(repoRoot, "common/color_definitions.scss"), colorDefinitionsScss);
console.log(
  `wrote common/color_definitions.scss (${swappableDecls.length} scheme-swappable tokens)`
);

// ---------------------------------------------------------------------------
// 2. nav.json -> javascripts/discourse/lib/hal0-nav-data.js
// ---------------------------------------------------------------------------

const nav = JSON.parse(readFileSync(navPath, "utf8"));

// Header nav, minus the forum entry itself (the forum IS this site — it
// gets aria-current on a hard-coded entry in the nav connector, not a
// duplicate link back to itself) and minus anything marked hidden.
const headerLinks = nav.header
  .filter((l) => l.label !== "forum" && !l.hidden)
  .map((l) => ({
    label: l.label,
    href: l.href,
    external: Boolean(l.external),
  }));

// Same self-link rule as the header above, applied to the footer: a link to
// forum.hal0.dev is useful chrome on hal0.dev and dead weight on the forum
// itself, so it is dropped from the theme's copy.
const FORUM_ORIGIN = "https://forum.hal0.dev";
const footerColumns = nav.footerColumns.map((col) => ({
  heading: col.heading,
  links: col.links
    .filter((l) => l.href !== FORUM_ORIGIN && l.href !== `${FORUM_ORIGIN}/`)
    .map((l) => ({
      label: l.label,
      href: l.href,
      external: Boolean(l.external),
    })),
}));

const social = nav.social || [];
const footerBase = (nav.footerBase || []).map((l) => ({
  label: l.label,
  href: l.href,
  external: Boolean(l.external),
}));

const navJs = `// AUTO-GENERATED by scripts/sync-from-hal0-web.mjs — do not edit by hand.
// Source: hal0-web src/data/nav.json
// Regenerate with: node scripts/sync-from-hal0-web.mjs [hal0-web-dir]
//
// hrefs are relative to hal0.dev (site-relative paths like "/docs/...").
// The connectors resolve them against the hal0_web_origin theme setting
// so links work regardless of which host the theme is installed on.

export const HAL0_HEADER_LINKS = ${JSON.stringify(headerLinks, null, 2)};

export const HAL0_FOOTER_COLUMNS = ${JSON.stringify(footerColumns, null, 2)};

export const HAL0_SOCIAL = ${JSON.stringify(social, null, 2)};

export const HAL0_FOOTER_BASE = ${JSON.stringify(footerBase, null, 2)};
`;

writeFileSync(resolve(repoRoot, "javascripts/discourse/lib/hal0-nav-data.js"), navJs);
console.log(`wrote javascripts/discourse/lib/hal0-nav-data.js (${headerLinks.length} header links, ${footerColumns.length} footer columns)`);
